<?php defined('SYSPATH') or die('No direct script access.');
class Controller_Erp412_Api extends Controller_Erp100_Base
{
 public $auto_render=FALSE;protected function s(){return Service_Erp412_Traceability::instance();}protected function actor(){return $this->_current_user?(int)$this->_current_user->id:NULL;}protected function acl($a){if(!$this->can($a))throw new HTTP_Exception_403('Доступ запрещён');}protected function method($m){if($this->request->method()!==$m)throw(new HTTP_Exception_405)->allowed(array($m));}protected function body(){$d=json_decode((string)$this->request->body(),TRUE);return is_array($d)?$d:(array)$this->request->post();}protected function out($fn){try{$this->response->headers('Content-Type','application/json; charset=utf-8')->body(json_encode(array('status'=>'ok','data'=>$fn()),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}catch(HTTP_Exception $e){throw $e;}catch(Throwable $e){$this->response->status(422)->body(json_encode(array('status'=>'error','message'=>$e->getMessage()),JSON_UNESCAPED_UNICODE));}}
 public function action_reference(){
  $this->acl('erp412.view');$q=trim((string)$this->request->query('q'));$type=(string)($this->request->query('type')?:'item');$items=array();
  if($type==='lot'){$rows=$this->s()->search(array('q'=>$q,'status'=>'available'),30);foreach($rows as $r)$items[]=array('id'=>$r['uuid'],'label'=>$r['lot_number'].($r['serial_number']?' · S/N '.$r['serial_number']:''),'context'=>$r['item_code'].' · '.$r['item_name'].' · '.$r['qty_trace']);}
  elseif($type==='order'){$rows=DB::query(Database::SELECT,"SELECT id,number,title,status FROM erp_402_orders WHERE (:q='' OR number ILIKE '%'||:q||'%' OR title ILIKE '%'||:q||'%') AND status IN('released','in_progress','done') ORDER BY id DESC LIMIT 30")->param(':q',$q)->execute()->as_array();foreach($rows as $r)$items[]=array('id'=>(int)$r['id'],'label'=>$r['number'].' · '.$r['title'],'context'=>$r['status']);}
  else{$rows=DB::query(Database::SELECT,"SELECT id,code,name FROM erp_227_objects WHERE is_latest=true AND is_deleted=false AND (:q='' OR code ILIKE '%'||:q||'%' OR name ILIKE '%'||:q||'%') ORDER BY name LIMIT 30")->param(':q',$q)->execute()->as_array();foreach($rows as $r)$items[]=array('id'=>(int)$r['id'],'label'=>$r['code'].' · '.$r['name'],'context'=>'Номенклатура');}
  $this->response->headers('Content-Type','application/json; charset=utf-8')->body(json_encode(array('items'=>$items),JSON_UNESCAPED_UNICODE));
 }
 public function action_lots(){$this->out(function(){$this->acl('erp412.view');return $this->s()->search($this->request->query(),$this->request->query('limit')?:50);});}
 public function action_get(){$this->out(function(){$this->acl('erp412.view');return $this->s()->get($this->request->param('id'));});}
 public function action_genealogy(){$this->out(function(){$this->acl('erp412.view');return $this->s()->genealogy($this->request->param('id'),$this->request->query('depth')?:20);});}
 public function action_create(){$this->out(function(){$this->method(Request::POST);$this->acl('erp412.manage');return $this->s()->create_lot($this->body(),$this->actor());});}
 public function action_from_movement(){$this->out(function(){$this->method(Request::POST);$this->acl('erp412.manage');$d=$this->body();return $this->s()->from_movement((int)Arr::get($d,'movement_id'),$d,$this->actor());});}
 public function action_allocate(){$this->out(function(){$this->method(Request::POST);$this->acl('erp412.manage');$d=$this->body();return $this->s()->allocate(Arr::get($d,'lot_id'),Arr::get($d,'movement_id'),Arr::get($d,'direction'),Arr::get($d,'qty'),Arr::get($d,'warehouse_id'),$this->actor());});}
 public function action_link(){$this->out(function(){$this->method(Request::POST);$this->acl('erp412.manage');return $this->s()->link($this->body(),$this->actor());});}
 public function action_production(){$this->out(function(){$this->method(Request::POST);$this->acl('erp412.manage');$d=$this->body();return $this->s()->record_production(Arr::get($d,'input_lot_id'),Arr::get($d,'output_lot_id'),Arr::get($d,'order_id'),Arr::get($d,'qty'),$this->actor());});}
 public function action_quality(){$this->out(function(){$this->method(Request::POST);$this->acl('erp412.quality');$d=$this->body();return $this->s()->link_inspection(Arr::get($d,'lot_id'),Arr::get($d,'inspection_id'),$this->actor());});}
 public function action_transition(){$this->out(function(){$this->method(Request::POST);$d=$this->body();$status=Arr::get($d,'status');$this->acl($status==='recalled'?'erp412.recall':'erp412.manage');return $this->s()->transition(Arr::get($d,'lot_id',$this->request->param('id')),$status,Arr::get($d,'reason'),$this->actor(),Arr::get($d,'reference_type'),Arr::get($d,'reference_id'));});}
}
